	$is_chunked = 1;
    }
    last if ($_ eq "\r\n");
}

$is_chunked || die "wasn't chunked\n";

for(;;) {
    $_ = <> || die "unexpected end of file!\n";

    m#^([0-9a-f]+) *\r$#i || die "bogus chunklen: $_";

    my $chunklen = hex($1);

    exit 0 if ($chunklen == 0);

    chop; chop;
    print "$_ ";

    my $data = '';
    read(ARGV, $data, $chunklen) == $chunklen || die "short read!\n";

    $_ = <> || die "unexpected end of file!\n";

    $_ eq "\r\n" || die "missing chunk trailer!\n";
}
