#include <stdio.h>
#include <string.h>
#include <assert.h>

#define MAXH 8

typedef struct {
    char key[32][64];
    char val[32][64];
    int n;
} headers_t;

static void h_init(headers_t *h) { h->n = 0; }
static void h_set(headers_t *h, const char *k, const char *v) {
    int i;
    for (i = 0; i < h->n; i++)
        if (!strcmp(h->key[i], k)) { snprintf(h->val[i], 64, "%s", v); return; }
    assert(h->n < 32);
    snprintf(h->key[h->n], 64, "%s", k);
    snprintf(h->val[h->n], 64, "%s", v);
    h->n++;
}
static const char *h_get(headers_t *h, const char *k) {
    int i;
    for (i = 0; i < h->n; i++)
        if (!strcmp(h->key[i], k)) return h->val[i];
    return NULL;
}
static void h_unset(headers_t *h, const char *k) {
    int i;
    for (i = 0; i < h->n; i++)
        if (!strcmp(h->key[i], k)) {
            int j;
            for (j = i; j < h->n - 1; j++) {
                memcpy(h->key[j], h->key[j + 1], 64);
